class IntStack{int[] a;int top=-1;IntStack(int n){a=new int[n];}void push(int v){if(top==a.length-1){System.out.println("Stack overflow");return;}a[++top]=v;}int pop(){if(top==-1){System.out.println("Stack underflow");return -1;}return a[top--];}void display(){if(top==-1){System.out.println("Stack is empty");return;}for(int i=top;i>=0;i--)System.out.println(a[i]);}} public class FixedSizeStack{public static void main(String[]x){IntStack s=new IntStack(5);s.push(10);s.push(20);s.push(30);s.display();System.out.println("Popped = "+s.pop());s.display();}}